import {handoffView} from './handoff-view';
import {freshAutomation,automationAction,automationReceipt} from './automation-lab.mjs';
import {automationView} from './automation-view';
import {freshTools,toolAction,toolReceipt} from './tool-lab.mjs';
import {toolView} from './tool-view';
import {freshSteering,steeringAction,steeringReceipt} from './steering-lab.mjs';
import {steeringView} from './steering-view';
