async function init(){try{const module=await startup.run('world-module',loadWorldModule);world=await module.createWorld(canvas,i=>start(i),id=>document.querySelector<HTMLButtonElement>(`[data-action="choice"][data-value="${id}"]`)?.click(),id=>{if(id==='__explore'){openDepth();return;}if(depth){stopDepthExample();updateDepth(['brief','old'].includes(id)?'source':'inspect',id);return;}document.querySelector<HTMLButtonElement>(`[data-action="context-inspect"][data-value="${id}"]`)?.click();},(action,id)=>document.querySelector<HTMLButtonElement>(`[data-action="model-${action}"][data-value="${id}"]`)?.click(),action=>{if(mission===3&&screen==='mission'&&!modal)handlePermission(action);},section=>{if(mission===7&&screen==='mission'&&!modal)handleReview('section',section);},action=>{if(mission===6&&screen==='mission'&&!modal)handleSteering(action,action.startsWith('send-')?steeringLab.messageKind:undefined);},section=>{if(mission===8&&screen==='mission'&&!modal)handleTools('section',section);},section=>{if(mission===10&&screen==='mission'&&!modal)handleAutomation('section',section);},section=>{if(mission===11&&screen==='mission'&&!modal)handleHandoff('section',section);},section=>{if(mission===12&&screen==='mission'&&!modal)handleCedar('section',section);},progress.settings.quality,updateQualityStatus,updateExhibitStatus,startup,updateQualityAdvice);applySettings();if(screen==='mission'){world.setLayout('mission');render();world.restoreView(Math.min(mission,11));}else world.gesture('Idle');if(paused)world.pause(true);startup.finish();}catch(error){startup.fail(error);graphicsError='3D couldn’t start in this browser.';console.error('Inside Codex startup failed',startup.state().failure);}ready=true;render();}
